export function multiCurveSVG(series,{xLabel='x',yLabel='y',cursor=null,includeZero=true}={}){
 const clean=(Array.isArray(series)?series:[]).map(s=>({...s,points:(Array.isArray(s?.points)?s.points:[]).filter(p=>Array.isArray(p)&&p.length>=2&&p.every(Number.isFinite))})).filter(s=>s.points.length);if(!clean.length)return "<p>The current data does not have this physical quantity.</p>";
 const ps=clean.flatMap(s=>s.points);let xmin=Math.min(...ps.map(p=>p[0])),xmax=Math.max(...ps.map(p=>p[0])),ymin=Math.min(...ps.map(p=>p[1])),ymax=Math.max(...ps.map(p=>p[1]));
 if(includeZero){ymin=Math.min(0,ymin);ymax=Math.max(0,ymax);}else{const pad=(ymax-ymin)*.08||Math.max(Math.abs(ymin)*.02,1);ymin-=pad;ymax+=pad;if(xmin===xmax){const xpad=Math.max(Math.abs(xmin)*.02,1);xmin-=xpad;xmax+=xpad;}}
 const dx=xmax-xmin||1,dy=ymax-ymin||1;
 const xy=p=>[80+570*(p[0]-xmin)/dx,255-210*(p[1]-ymin)/dy];
 return `<svg class="obs-curve" viewBox="0 0 720 340" role="img" aria-label="${esc(yLabel)} with ${esc(xLabel)} change"><title>${svgMathText(yLabel)}</title><path d="M80 35V255H660" fill="none" stroke="#9eb3a5"/>${[0,.5,1].map(t=>`<line x1="80" x2="660" y1="${255-t*210}" y2="${255-t*210}" stroke="#dce6df"/><text x="70" y="${261-t*210}" text-anchor="end">${num(ymin+t*dy)}</text>`).join('')}${clean.map((s,i)=>s.points.length===1?`<circle cx="${xy(s.points[0])[0]}" cy="${xy(s.points[0])[1]}" r="4" fill="${palette[i%4]}"/>`:`<polyline points="${s.points.map(p=>xy(p).join(',')).join(' ')}" fill="none" stroke="${palette[i%4]}" stroke-width="3"/>`).join('')}${Number.isFinite(cursor)?`<path d="M${xy([cursor,0])[0]} 35V255" stroke="#aa7252" stroke-dasharray="4 4"/>`:''}<text x="80" y="282">${num(xmin)}</text><text x="650" y="282" text-anchor="end">${num(xmax)}</text><text x="90" y="23">${svgMathText(yLabel)}</text><text x="360" y="317" text-anchor="middle">${svgMathText(xLabel)}</text></svg><div class="mr-legend">${clean.map((s,i)=>`<span><i style="background:${palette[i%4]}"></i>${esc(s.label)}</span>`).join('')}</div>`;
}
export function connectionSVG(result){
 const groups=[0,1,2].map(col=>result.nodes.filter(n=>n.column===col)),positions=new Map();groups.forEach((g,col)=>g.forEach((n,i)=>positions.set(n.id,[100+250*col,95+(i-(g.length-1)/2)*85+50])));
 return `<svg class="obs-curve" viewBox="0 0 720 310" role="img" aria-label="Compatible connection diagram from endpoint representation to line representation"><title>Connections generated by  restricted representation   multiplicity ; these are not energy coordinates</title>${result.edges.map(e=>{const a=positions.get(e.from),b=positions.get(e.to);if(!a||!b)return '';return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${result.active?'#40856f':'#a5ada6'}" stroke-width="3" ${result.active?'':'stroke-dasharray="5 4"'}/>`;}).join('')}${result.nodes.map(n=>{const p=positions.get(n.id);return `<circle cx="${p[0]}" cy="${p[1]}" r="7" fill="#247b65"/><text x="${p[0]}" y="${p[1]-18}" text-anchor="middle">${esc(n.label)}</text>`;}).join('')}<text x="360" y="278" text-anchor="middle">${result.active?"Symmetry Preservation: Branch Compatibility":"Symmetry breaking: dashed curves show only the parent-phase reference"}</text></svg>`;
}
export function frozenStructureSVG(frozen,yaw=-35){
 const atoms=frozen?.atoms||[],cell=frozen?.lattice;if(!atoms.length||!cell)return '';
 const cart=p=>[0,1,2].map(j=>p.reduce((s,v,i)=>s+v*cell[i][j],0)),vertices=Array.from({length:8},(_,i)=>cart([i&1?1:0,i&2?1:0,i&4?1:0])),edges=[];for(let i=0;i<8;i++)for(const k of [1,2,4])if(i<(i^k))edges.push([i,i^k]);
 const a=yaw*Math.PI/180,raw=p=>[Math.cos(a)*p[0]-Math.sin(a)*p[1],.4*(Math.sin(a)*p[0]+Math.cos(a)*p[1])-p[2]],bounds=[...vertices,...atoms.flatMap(x=>[x.equilibrium,x.position])].map(raw),xs=bounds.map(p=>p[0]),ys=bounds.map(p=>p[1]),lo=[Math.min(...xs),Math.min(...ys)],hi=[Math.max(...xs),Math.max(...ys)],scale=Math.min(550/(hi[0]-lo[0]||1),285/(hi[1]-lo[1]||1)),project=p=>raw(p).map((v,i)=>(i?190:340)+(v-(hi[i]+lo[i])/2)*scale),species=[...new Set(atoms.map(x=>x.symbol))];
 return `<svg class="mr-view" viewBox="0 0 680 390" role="img" aria-label="Frozen-mode structure; hollow markers indicate original positions"><title>frozen structure; the hollow circle represents the equilibrium position, and the line segment represents the real displacement</title>${edges.map(([i,j])=>{const p=project(vertices[i]),q=project(vertices[j]);return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="#bacdbe"/>`;}).join('')}${atoms.map(atom=>{const p=project(atom.equilibrium),q=project(atom.position);return `<circle cx="${p[0]}" cy="${p[1]}" r="11" fill="none" stroke="#839c8c" stroke-dasharray="3 3"/><line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="#ad7f34" stroke-width="3"/><circle cx="${q[0]}" cy="${q[1]}" r="8" fill="${palette[species.indexOf(atom.symbol)%4]}"/>${atoms.length<=40?`<text x="${q[0]+10}" y="${q[1]-9}">${esc(atom.symbol)}</text>`:''}`;}).join('')}</svg>`;
}
